#!/usr/bin/env python3
"""Deterministically build the session-scoped CNY→USD research dashboard."""
from pathlib import Path
import csv, html, json, re
ROOT = Path(__file__).resolve().parent
REPO = ROOT.parent
OUT = ROOT
DATA = ROOT / 'data'
SRC = REPO / 'repatriate' / 'data'

sources_doc = json.loads((SRC/'sources.json').read_text())
methods_doc = json.loads((SRC/'methods.json').read_text())
rules_doc = json.loads((SRC/'rules.json').read_text())
flags_doc = json.loads((SRC/'flags.json').read_text())
sources = {s['id']: s for s in sources_doc['sources']}
methods = methods_doc['methods']
flags = flags_doc['flags']

# Carry forward the source/method catalog and already generated scenario model,
# with an explicit source-checked ledger documenting what was freshly re-fetched.
(DATA/'sources.json').write_text(json.dumps(sources_doc, ensure_ascii=False, indent=2)+'\n')
(DATA/'methods.json').write_text(json.dumps(methods_doc, ensure_ascii=False, indent=2)+'\n')
(DATA/'flags.json').write_text(json.dumps(flags_doc, ensure_ascii=False, indent=2)+'\n')
(DATA/'rules.json').write_text(json.dumps(rules_doc, ensure_ascii=False, indent=2)+'\n')
with (REPO/'repatriate/exports/cost-ladders.csv').open(newline='') as f:
    cost_rows = list(csv.DictReader(f))
(DATA/'costs.json').write_text(json.dumps(cost_rows, ensure_ascii=False, separators=(',', ':'))+'\n')

