def esc(x): return html.escape(str(x), quote=True)
def link(sid):
 s=sources.get(sid)
 return f'<a href="{esc(s["url"])}" target="_blank" rel="noopener" title="{esc(s["title"])}">{esc(sid)} · {esc(s["publisher"])}</a>' if s else ''
def ref_ids(text):
 def repl(m):
  sid=m.group(1)
  return f'<a href="sources.html#{sid}">{sid}</a>' if sid in sources else m.group(0)
 return re.sub(r'\b(S\d{2})\b',repl,esc(text))
def nav(active):
 items=[('index.html','Summary'),('methods.html','Methods'),('costs.html','Cost ladder'),('penalties.html','Penalty breakdown'),('taxes.html','Taxes & reporting'),('sources.html','Sources'),('flagged.html','Flagged for review'),('verification.html','Verification')]
 return '<nav aria-label="Research sections">'+''.join(f'<a class="{"active" if href==active else ""}" href="{href}">{name}</a>' for href,name in items)+'</nav>'
def wrap(title,body,active):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | China to USD research</title><meta name="description" content="Source-linked research on lawful CNY to USD conversion, transfer methods, costs and tax/reporting distinctions for a US citizen."><link rel="stylesheet" href="assets/style.css"></head><body><header><h1>China money · CNY → USD research</h1><p>U.S.-citizen perspective · sources linked · unknowns left blank</p></header>{nav(active)}<main>{body}<div class="footer">Research, not personalized legal/tax advice. No funds moved. Prices shown only where published in a cited provider tariff; FX quote, tax liability and total delivered USD are not assumed. Source register and verification limits are explicit. <a href="../">Repository hub</a>.</div></main></body></html>'''

def table(headers,rows):
 return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'

# Summary landing/executive summary.
body='''<section class="hero"><span class="pill conditional">Best-supported first route · conditional</span><h2>Executive summary</h2><p class="lead">The official sources reviewed do not establish a general stand-alone tax on exchanging CNY for USD; that does not rule out tax on the underlying income, an asset sale, or a separate currency gain. The likely lawful first path for a U.S. citizen who is a non-mainland-Chinese individual and can document lawful PRC current-account income is: take proof of the source and PRC tax vouchers to the China bank, convert the documented eligible amount, and remit to an account in your own name. <a href="sources.html#S03">SAFE’s current guidance</a> requires ID and transaction-amount documents including tax vouchers; it does not quote a flat annual cap for that documented-income route.</p><div class="actions"><a href="methods.html">Compare 17 routes</a><a class="secondary" href="costs.html">Open 40-tier cost ladder</a><a class="secondary" href="penalties.html">Understand each “penalty”</a></div></section>
<div class="callout warn"><strong>Bottom line:</strong> the repo cannot conclude your cheapest route, net USD, or China/US tax due without knowing how the CNY was earned/acquired, your immigration/PRC status, tax-paid documents, property/inheritance facts, and actual bank/provider quote. These values are intentionally blank. A transfer of existing principal is not automatically taxable income; tax on the source income or asset event is separate.</div>
<div class="grid"><div class="card metric"><strong>17</strong><span>catalogued routes (lawful, conditional and rejected)</span></div><div class="card metric"><strong>680</strong><span>cost scenarios: 17 methods × $10k through $400k</span></div><div class="card metric"><strong>40 tiers</strong><span>each method; fees blank when not statically verifiable</span></div><div class="card metric"><strong>2026-11-10</strong><span>official-source re-check date for listed verification ledger</span></div></div>
<h2>What to do first (no funds moved)</h2><div class="card"><ol><li>Classify the source of the RMB (salary, business/service income, property sale, inheritance, savings, foreign-currency reconversion, or another source). Do not label ordinary savings as income without evidence.</li><li>Collect passport/ID, account ownership and bank statements, source-of-funds records, PRC tax vouchers/filings, employment/property/inheritance documents as applicable, and any original USD→RMB exchange memo.</li><li>Ask your China bank, in writing, whether it will process conversion for your exact source category and documents; request the executable CNY/USD rate, SWIFT charges, correspondent/receiving fees, transfer limits, and written required-document list before authorizing.</li><li>For documented lawful current-account RMB income, ask about SAFE-guidance route (M01). For unused RMB originally exchanged from foreign currency, ask about the limited receipt-backed reconversion route (M09). Do not use other people’s quotas, false paperwork, underground channels or crypto.</li><li>Report foreign accounts/income correctly in the U.S. FBAR/Form 8938/tax returns as applicable. FBAR is separate from income tax and is generally triggered by aggregate foreign-account value above $10,000 at any time in the year.</li></ol><div class="sources">Source basis: {link('S03')} {link('S04')} {link('S17')} {link('S18')}</div></div>
<h2>Decision in one minute</h2>'''
quick=[('Documented China-earned current-account income','M01 — ask bank to convert/remit amount supported by ID + transaction materials including tax vouchers. No fixed USD cap stated in the cited SAFE Q&A.','S03;S05;S29'),('Unused RMB originally exchanged from foreign currency','M09 — locate original exchange memo, check 24-month validity and unused amount; small ID-only amounts are limited. Not a workaround for ordinary RMB savings.','S04;S01'),('Foreign Permanent Resident ID Card or PRC ID','M02 — annual facilitation quota may apply if eligible. US passport alone is not evidence of quota eligibility.','S01;S05'),('Ordinary accumulated savings with no qualifying source documents','No approved route is confirmed by this research. Do not disguise source or split transfers; ask bank/SAFE what documentary route applies.','S06;S13'),('Emigration/inheritance/proceeds of property sale','Only if facts qualify; separate SAFE asset-transfer process or documented sale proceeds. Not a general savings-balance route.','S06;S08;S09'),('Crypto, underground swap, pooled quotas or fabricated documents','Do not use. Current PBOC notice and FX regulations flag legal prohibitions/serious consequence exposure.','S06;S13;S14')]
body+='''<div class="grid">'''+''.join(f'<div class="card"><h3>{esc(a)}</h3><p>{esc(b)}</p><div class="sources">'+''.join(link(s) for s in c.split(';'))+'</div></div>' for a,b,c in quick)+'''</div><h2>Do not confuse the five “penalty” buckets</h2><div class="grid"><div class="card"><b>1. Source tax</b><p>Tax on wages, gains, property, interest or another taxable event, based on the underlying facts. Not a remittance fee.</p><div class="sources">'''+link('S15')+'''</div></div><div class="card"><b>2. FX spread</b><p>Difference between the bank/provider quote and a reference rate. No static current spread verified; the IRS yearly average is not an executable rate.</p><div class="sources">'''+link('S23')+'''</div></div><div class="card"><b>3. Transfer charges</b><p>Published bank tariff items may be countable; intermediary, receiving, and provider fees may be extra or quote-only.</p><div class="sources">'''+link('S29')+'''</div></div><div class="card"><b>4. Currency gain</b><p>Potential separate U.S. tax issue under currency rules; depends on how/when the CNY was acquired and disposed of. Not computed here.</p><div class="sources">'''+link('S24')+'''</div></div><div class="card"><b>5. Reporting penalties</b><p>Possible consequences for missed FBAR/Form 8938 or cash reports; not a tax on conversion itself. Filing thresholds differ.</p><div class="sources">'''+link('S17')+link('S18')+link('S28')+'''</div></div></div><div class="callout"><strong>See:</strong> <a href="penalties.html">Penalty breakdown</a>, <a href="taxes.html">Taxes & reporting</a>, <a href="flagged.html">Flagged for review</a>, and source-by-source <a href="verification.html">verification ledger</a>.</div>'''
(OUT/'index.html').write_text(wrap('Executive summary',body,'index.html'))

# Method catalog with citations on every method row and each claim rendered with source ids linked.
sections=[]
for m in methods:
 pros=''.join(f'<li>{ref_ids(x)}</li>' for x in m['pros'])
 cons=''.join(f'<li>{ref_ids(x)}</li>' for x in m['cons'])
 steps=''.join(f'<li>{ref_ids(x)}</li>' for x in m['steps'])
 srcs=''.join(link(s) for s in m['sources'])
 cls='rejected' if m['status']=='rejected-unlawful' else 'conditional'
 sections.append(f'<article class="method" id="{m["id"]}"><h3>{esc(m["id"])} · {esc(m["name"])} <span class="pill {cls}">{esc(m["status"])}</span></h3><p><b>Who / eligibility:</b> {ref_ids(m["who"])}</p><div class="cols"><div><b>Pros</b><ul>{pros}</ul></div><div><b>Cons / cautions</b><ul>{cons}</ul></div></div><details><summary>Step-by-step (conditional on bank/provider approval)</summary><ol>{steps}</ol></details><div class="sources">Primary sources: {srcs}</div><p><a href="costs.html?method={m["id"]}">View all 40 cost tiers for {m["id"]}</a></p></article>')
body='<h2>All transfer / conversion routes</h2><p class="lead">Routes are categorized by what they actually authorize, who may qualify and whether the path fits ordinary personal savings. A listed method is not a recommendation or guaranteed bank acceptance.</p><div class="callout warn"><b>Most likely for a U.S. citizen:</b> documented-income bank conversion/remittance (M01) when the balance is traceable to lawful current-account income and tax vouchers exist. A U.S. citizen is not presumed eligible for the PRC ¥50,000 equivalent purchase facilitation quota. Every route below has source-linked steps and cost detail.</div>'+''.join(sections)
(OUT/'methods.html').write_text(wrap('Methods',body,'methods.html'))

# Cost ladder: each scenario has its own click-through source links and blank cells are not fabricated.
body='''<h2>Transfer & conversion cost ladder · 17 methods × 40 amounts</h2><p class="lead">The ladder covers every requested amount from USD 10,000 to USD 400,000 in USD 10,000 increments. Use filters to view a method or tier. Best-known published fees appear first; blanks mean no static fee was source-verified. This is not total cost or a live quote.</p><div class="callout warn"><b>Critical:</b> “published transfer fee” excludes unverified FX spread, other-bank/intermediary charges, travel/cash risk, quote-only provider fees, and source tax. For M01, HSBC Premier/Advance tariff base fee is min/max capped + cable fee; amounts are computed at 7.129 CNY/USD reference rate (S23). It assumes a single wire and eligible account segment. The USD 400k row is a computed CNY 620 fee = about USD 86.97, not an all-in quote. No benefit of lowest cost is certified across providers.</div><div class="filter"><label>Method<select id="methodFilter"><option value="">All 17 methods</option>'''+''.join(f'<option value="{m["id"]}">{m["id"]} · {esc(m["name"])}</option>' for m in methods)+'''</select></label><label>Amount (USD)<select id="amountFilter"><option value="">All 40 amounts</option>'''+''.join(f'<option value="{a}">${a:,}</option>' for a in range(10000,400001,10000))+'''</select></label><label>Search<input id="searchFilter" placeholder="e.g. bank wire, Wise, unlawful"></label></div><p id="costCount" class="small" aria-live="polite"></p><div id="costResults"></div><noscript><p>JavaScript is required to filter/display the 680 cost scenarios. The source CSV and JSON are available in <a href="data/costs.json">JSON</a> and the repository's <a href="../repatriate/exports/cost-ladders.csv">CSV export</a>.</p></noscript><p class="small">Underlying computed model uses current scenario generator carried forward from repatriate; see <a href="../repatriate/build.py">model code</a>, <a href="data/verification.json">fresh verification ledger</a>, <a href="flagged.html">flags</a>. Calculated scenarios for rejected methods show statutory exposure separately; such values are not a “price” or advice to do the unlawful method.</p>'''
(OUT/'costs.html').write_text(wrap('Cost ladder',body,'costs.html'))

js='''async function initCosts(){const [rows,methods,sources]=await Promise.all([fetch('data/costs.json').then(r=>r.json()),fetch('data/methods.json').then(r=>r.json()),fetch('data/sources.json').then(r=>r.json())]);const mm=Object.fromEntries(methods.methods.map(x=>[x.id,x]));const ss=Object.fromEntries(sources.sources.map(x=>[x.id,x]));const mf=document.querySelector('#methodFilter'),af=document.querySelector('#amountFilter'),sf=document.querySelector('#searchFilter'),box=document.querySelector('#costResults'),count=document.querySelector('#costCount');const params=new URLSearchParams(location.search);if(params.has('method'))mf.value=params.get('method');function render(){const term=sf.value.toLowerCase(),method=mf.value,amount=af.value;const selected=rows.filter(r=>(!method||r.method===method)&&(!amount||r.amount_usd===amount)&&(!term||(mm[r.method].name+' '+r.method+' '+r.constraint+' '+r.constraint_detail).toLowerCase().includes(term)));count.textContent=`Showing ${selected.length} of ${rows.length} independently source-linked scenarios.`;box.innerHTML=selected.map(r=>{const m=mm[r.method],good=m.status==='lawful-conditional';let price='';if(r.published_fee_usd!=='')price=`$${Number(r.published_fee_usd).toFixed(2)} published-fee reference`;else if(r.fine_standard_max_usd!=='')price='Not a cost · legal exposure below';else price='<span class="unknown">Blank · unverified / not statically published</span>';const ids=r.sources.split(';').filter(Boolean);const cites=ids.map(id=>ss[id]?`<a href="sources.html#${id}" title="${escJs(ss[id].title)}">${id} · ${escJs(ss[id].publisher)}</a>`:'').join('');let fine='';if(r.fine_standard_max_usd!=='')fine=`<p><b>Illustrative statutory exposure, not fee:</b> standard maximum ${r.fine_standard_max_usd?`$${Number(r.fine_standard_max_usd).toLocaleString()}`:'—'}; serious band ${r.fine_serious_min_usd?`$${Number(r.fine_serious_min_usd).toLocaleString()}`:'—'}–${r.fine_serious_max_usd?`$${Number(r.fine_serious_max_usd).toLocaleString()}`:'—'}. Depends on legal classification and circumstances; see linked statute.</p>`;return `<article class="cost-card"><div class="cost-top"><div><span class="badge">${r.method} · $${Number(r.amount_usd).toLocaleString()}</span><h3>${escJs(m.name)}</h3></div><div class="cost-price">${price}</div></div><p><b>Constraint:</b> ${escJs(r.constraint)}. ${escJs(r.constraint_detail)}</p>${r.published_fee_cny!==''?`<p class="small">Published tariff basis: CNY ${Number(r.published_fee_cny).toLocaleString()} (reference conversion only). FX spread and correspondent fees are not included.</p>`:''}${fine}<div class="sources">Row sources: ${cites}</div><p class="small"><a href="methods.html#${r.method}">Eligibility, pros/cons & steps</a> · <a href="flagged.html">relevant limitations</a></p></article>`}).join('')||'<div class="card">No rows match. Adjust the filters.</div>'}mf.addEventListener('change',render);af.addEventListener('change',render);sf.addEventListener('input',render);render()}function escJs(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}if(document.querySelector('#costResults'))initCosts().catch(e=>{document.querySelector('#costResults').textContent='Cost data could not be loaded; consult the repository JSON/CSV exports.';console.error(e)});'''
(OUT/'assets/app.js').write_text(js)

# Penalty analysis: distinctions, source-linked rows, no inferred personal tax amounts.
rows=[
['Source tax / PRC income tax','Tax obligation attached to how the RMB was earned or to an asset transaction, not the act of wiring it. Comprehensive income: progressive 3–45%; certain categories incl. asset transfer: 20%. Property-transfer tax base is not gross remittance amount.','Personal amount blank: source type, residency, basis, deductions and prior tax facts unknown.','S15;S03'],
['FX spread / exchange-rate loss','Difference between actual bank/provider execution rate and a chosen benchmark. The IRS explicitly says it has no official exchange rate; annual average is a tax-reporting comparison tool, not an executable quote.','Blank: no live provider quote or spread schedule verified.','S23;S29'],
['Bank transfer charges','Published service tariff per transfer (e.g. HSBC Premier/Advance TT issue fee plus cable charge).','Published portion modelled only; excludes third-party charges and FX rate margin; transaction count/account segment may change total.','S29;S23'],
['Correspondent / receiving charges','Other banks or intermediaries may charge separately; HSBC tariff note excludes these charges.','Blank: actual route/bank charge not statically published.','S29'],
['Currency gain/loss under U.S. rules','Potential separate U.S. currency gain/loss question; exchange-rate movements between acquisition and disposition may matter depending on transaction characterization.','Blank: acquisition history, basis, holding/personal-use classification and current law analysis absent. 26 USC 988 source in repo is 2024 edition and flagged.','S24;S23'],
['U.S. foreign tax credit','A limited credit may be available for qualifying foreign income tax; it is not automatic dollar-for-dollar reimbursement and has category/source limitations.','Blank: foreign income category, U.S. taxable income and credit limit not given.','S20'],
['FBAR / Form 8938 reporting violations','Possible reporting penalties for failing to file required forms; these are not remittance tax or conversion charges. Requirements and agencies differ.','No personal penalty determined. Filing status/history/private facts unknown.','S17;S18;S19'],
['Cash carry reporting','U.S. border report applies when currency/monetary instruments exceed $10,000 at one time, including family/group aggregate. Filing is reporting, not a tax.','No personal penalty or carry scenario assumed.','S28'],
['PRC FX evasion / illegal private exchange','Regulatory fine exposure may apply to evasion, fraudulent purchases, unauthorized private/indirect FX trades; statute includes graduated bands, repatriation/reconversion orders and possible criminal liability.','Do not use as an expected cost. Exact classification and enforcement consequences depend on facts.','S13;S06'],
['Virtual currency route','PBOC 2026 notice treats specified virtual-currency business as illegal financial activity in China; financial institutions are barred from related account/transfer/settlement services.','Rejected route; no price estimate or instructions.','S14;S13']]
rows_html=[]
for label,meaning,unknown,ids in rows:
 rows_html.append([esc(label),esc(meaning),esc(unknown),''.join(link(x) for x in ids.split(';'))])
body='<h2>“Conversion penalty” is not one tax</h2><p class="lead">Separate source tax, exchange rate, transfer fees, currency gain/loss, and filing penalties. Calling all of these a “tax penalty” hides what may be avoidable, what depends on the facts, and what cannot be priced before a live quote.</p><div class="callout danger"><b>Never assume “already taxed in China = no U.S. tax.”</b> U.S. citizens generally remain subject to U.S. tax rules on worldwide income; foreign tax credits may reduce double taxation only within limits and requirements. Moving principal is distinct from recognizing income or gains.</div>'+table(['Cost / exposure type','What it means','What can be quantified here','Official / primary source'],rows_html)+'<h2>HSBC example: posted transfer-fee floor only</h2><p>For Premier/Advance outward TT, the tariff lists an issuance charge of 0.1% subject to CNY 100 minimum and CNY 500 maximum, plus CNY 120 cable charge. The table below isolates that charge only for one assumed wire and converts it using the IRS 2025 annual average of 7.129 CNY/USD. That reference is not a bank rate. For a $10k transfer, fee = CNY 220 = about $30.86. For $400k, fee = CNY 620 = about $86.97. Neither figure includes FX spread, correspondent charges, tax, or bank-specific transfer acceptance/limits.</p>'+table(['Tier','HSBC fee CNY','Approx. reference USD','What is excluded','Sources'],[[f'${a:,}','220' if a==10000 else '620' if a==400000 else '100–620*','30.86' if a==10000 else '86.97' if a==400000 else '','FX spread, other-bank charges, source tax, and live quote',''.join(link(x) for x in ['S29','S23'])] for a in [10000,400000]])+'<p class="small">*For intermediate amounts the modeled base fee is 0.1% of remittance subject to tariff minimum/maximum, plus CNY120. The full 40-tier × 17-method dataset is in <a href="costs.html">Cost ladder</a>; no unverified costs are filled.</p><h2>PRC fine exposure: not a price to budget</h2><div class="callout warn">The cited FX Regulation Arts. 39/40/45 prescribe generally up to 30% in ordinary cases and over 30% up to an equivalent amount in serious cases for specified violations; other remedies and criminal liability may apply. Do not treat an alleged fine as a predictable fee or as an acceptable cost of bypassing conversion rules. Applicable article and exact amount depend on legal facts.</div><div class="sources">Read the Chinese SAFE-hosted regulation: '+link('S13')+link('S06')+'</div><h2>Penalty calculation is intentionally blank for this person</h2><p>No personal PRC income tax, U.S. income tax, tax credit, currency gain, net proceeds, or reporting penalty is calculated. The necessary private facts and/or live rates are not present. The status of unknowns is listed on the <a href="flagged.html">Flagged for review</a> page.</p>'
(OUT/'penalties.html').write_text(wrap('Penalty breakdown',body,'penalties.html'))

# Taxes/reporting table rows all cited.
taxrows=[
['Tax on source income','Income/source event','PRC IIT law provides 3–45% progressive rates for comprehensive income; 20% for listed passive/asset-transfer/incidental categories. Tax residency, category, base, exemptions and prior payment matter.','No personal figure. Conversion itself not shown as a standalone tax in cited source.','S15'],
['U.S. worldwide income','U.S. citizen','U.S. citizen abroad may still owe U.S. tax on worldwide income; foreign tax credit/exclusion applicability is conditional.','No personal tax/credit computed.','S16;S20;S21'],
['Foreign tax credit','Qualifying foreign income tax','Credit is limited by foreign-source taxable-income fraction; unused credits may carry back/forward subject to rules.','No credit amount calculable. Do not assume full offset.','S20'],
['FBAR / FinCEN 114','Foreign financial accounts','U.S. person generally files if aggregate foreign account value exceeds USD 10,000 at any time in calendar year. Separate from tax return; taxable income is irrelevant to the FBAR trigger.','Threshold verified; account status and filing history unknown.','S17'],
['Form 8938','Specified foreign assets','Separate form/thresholds; for unmarried person living abroad, IRS comparison shows >$200,000 year-end or >$300,000 anytime; other statuses differ.','Threshold depends on residence, marital status and assets.','S18'],
['Foreign currency gain/loss','Currency disposition','Potential U.S. currency rules may apply; statute copy in project is 2024 edition.','Blank; basis, holding and personal-vs-investment status unknown; flagged for current-law/professional review.','S24;S23'],
['Cash crossing U.S. border','Currency / monetary instruments','More than $10,000 at one time must be reported; family/group aggregate applies. Reporting is not a tax.','No personal carry planned or assumed.','S28'],
['PRC emigration tax filing','Emigration asset transfer only','PBOC/SAFE process can require tax clearance; narrow route tied to qualifying emigration or inheritance, not ordinary account balance.','Eligibility unknown; most U.S.-born citizens do not fit emigrant category absent Mainland emigration history.','S08;S09;S15']]
rows_html=[[esc(a),esc(b),esc(c),esc(d),''.join(link(x) for x in e.split(';'))] for a,b,c,d,e in taxrows]
body='<h2>Taxes and reporting are separate tracks</h2><div class="callout"><b>Safe sequence:</b> identify income/asset event and PRC tax documentation; separately obtain bank conversion approval; separately comply with U.S. income-tax and foreign-account reporting. “Tax paid” does not waive the need to establish eligibility or file disclosure forms.</div>'+table(['Topic','Applies to','Verified rule / distinction','What remains unknown','Sources'],rows_html)+'<h2>U.S. filing reminder</h2><p>IRS explains FBAR is electronically filed with FinCEN, not attached to the U.S. income tax return. FBAR and Form 8938 have different thresholds and can both apply. Consult current IRS forms/instructions for filing year; the thresholds above are not a calculation of your liability.</p><div class="sources">'+link('S17')+link('S18')+link('S16')+'</div><h2>What counts as source tax vs transfer “penalty”?</h2><ul><li>Income tax generally relates to the underlying source/event (wages, services, rent, sale gain, dividends), not the transfer of already-owned bank principal. Classification and tax basis must be determined from actual records.</li><li>A tariff or exchange spread is a financial cost, not a tax. Only a live exact-amount provider quote can establish the executed rate and fees.</li><li>FBAR, Form 8938 and cash reporting are disclosure duties with potential penalties for noncompliance; the filing trigger is not a tax charge on conversion.</li></ul>'
(OUT/'taxes.html').write_text(wrap('Taxes and reporting',body,'taxes.html'))

# Sources and factual provenance.
body='<h2>Sources and source-check status</h2><p class="lead">Open source link for manual review. Sources S01–S31 are the session’s repository register. “Fetched this session” is restricted to the explicitly listed verification ledger; other source entries are carried forward and not misrepresented as freshly checked here.</p><div class="callout warn">Primary sources include regulators, statutes, IRS/CBP, and the provider’s own tariff/help page. Provider pages establish that provider’s offered terms, not a regulator guarantee. For Chinese rules, Chinese official version controls over unofficial/translated interpretations.</div>'
for s in sources_doc['sources']:
 checked=any(x["source"]==s["id"] for x in verified)
 fresh=f'<a href="verification.html#{s["id"]}">Checked 2026-11-10</a>' if checked else 'Not freshly re-fetched in this session'
 body+=f'<article class="method" id="{s["id"]}"><h3>{esc(s["id"])} · {esc(s["title"])}</h3><p><b>Publisher:</b> {esc(s["publisher"]) } · <b>Type:</b> {esc(s["kind"])} · <b>Repository status:</b> {esc(s["status"])}</p><p><b>Locator:</b> {esc(s.get("locator",""))}</p><p><b>Source register synopsis:</b> {esc(s.get("facts",""))}</p><p><a href="{esc(s["url"])}" target="_blank" rel="noopener">Open primary source</a></p><p class="small">Fresh verification: {fresh}</p></article>'
(OUT/'sources.html').write_text(wrap('Sources',body,'sources.html'))

# Flags.
body='<h2>Flagged for review · unknowns stay blank</h2><p class="lead">These points are disclosed rather than hidden. A flagged item does not block publication. Every source-backed flag links directly to the official/provider-primary source. This page also calls out known inconsistencies and limits in the multi-session repository.</p>'
for f in flags:
 refs=''.join(link(s) for s in f.get('sources',[]))
 body+=f'<article class="method" id="{f["id"]}"><h3>{esc(f["id"])} · {esc(f["title"])} <span class="pill flag">{esc(f["severity"])}</span></h3><p>{esc(f["detail"])}</p><div class="sources">Source review: {refs if refs else "No official source; repository inconsistency noted as a project-wide issue."}</div></article>'
(OUT/'flagged.html').write_text(wrap('Flagged for review',body,'flagged.html'))

# Verification ledger.
body='<h2>Line-by-line source verification log</h2><p class="lead">Each entry records the exact official/provider page or PDF fetched on 2026-11-10, its relevant locator, the specific conclusion supported, and scope limits. This is not a blanket assertion that every repo claim has been freshly re-verified.</p><div class="callout danger"><b>Important source correction:</b> SAFE’s current documented-income FAQ requires “valid ID and source materials with transaction amount (including tax vouchers).” It does not give a numeric annual cap in the quoted FAQ. Conversely, the USD 500/USD 1,000 small-amount rule applies only to reconverting unused RMB originally exchanged from FX. Do not generalize that allowance to ordinary CNY savings.</div>'
vr=[]
for v in verified:
 vr.append([f'<a id="{v["source"]}" href="{esc(v["url"])}" target="_blank" rel="noopener">{esc(v["source"])} · open source</a>',esc(v['locator']),esc(v['verified']),esc(v['result']),esc(v['scope'])])
body+=table(['Source','Locator','Checked','What page actually states','Claim scope / limits'],vr)+'<h2>Audit boundaries</h2><ul><li>Freshly fetched evidence is limited to entries in this table. Remaining S01–S31 sources are linked in <a href="sources.html">Sources</a> but marked not freshly fetched.</li><li>Rows in cost ladder cite their underlying source IDs. Values derive from the existing deterministic model; their input/source limitations are disclosed in each row.</li><li>Verification confirms what cited pages say, not eligibility, bank acceptance, a live FX price, account ownership, personal tax, or legal advice.</li><li>Potentially serious errors affecting a conversion decision are made visible in <a href="flagged.html">Flagged for review</a>.</li></ul>'
(OUT/'verification.html').write_text(wrap('Verification ledger',body,'verification.html'))
print(f'Built {len(methods)} methods, {len(cost_rows)} cost tiers, {len(sources)} sources, {len(flags)} flags, {len(verified)} fresh source checks.')
